import type { Fetch } from './fixtures'

export interface ConnectorConfig {
  /** Shopify shared secret for HMAC-SHA256 verification (env: SHOPIFY_CLIENT_SECRET) */
  shopifyClientSecret: string
  /** Slack bot token with chat:write scope (env: SLACK_BOT_TOKEN) */
  slackBotToken: string
  /** Slack channel ID to post the order summary (env: SLACK_CHANNEL_ID) */
  slackChannel: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: Fetch
}

export interface ShopifyOrderPayload {
  id: number
  name: string
  email: string
  total_price: string
  line_items: Array<{
    title: string
    quantity: number
    price: string
  }>
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be a non-null object')
  }
  const p = payload as Record<string, unknown>
  const required = ['id', 'name', 'email', 'total_price', 'line_items'] as const
  for (const field of required) {
    if (!(field in p) || p[field] === undefined || p[field] === null) {
      throw new Error(`Missing required field: ${field}`)
    }
  }
  if (typeof p.id !== 'number') throw new Error('Field "id" must be a number')
  if (typeof p.name !== 'string') throw new Error('Field "name" must be a string')
  if (typeof p.email !== 'string') throw new Error('Field "email" must be a string')
  if (typeof p.total_price !== 'string') throw new Error('Field "total_price" must be a string')
  if (!Array.isArray(p.line_items)) throw new Error('Field "line_items" must be an array')
  for (const [idx, item] of p.line_items.entries()) {
    if (!item || typeof item !== 'object') throw new Error(`line_items[${idx}] must be an object`)
    const li = item as Record<string, unknown>
    if (typeof li.title !== 'string') throw new Error(`line_items[${idx}].title must be a string`)
    if (typeof li.quantity !== 'number') throw new Error(`line_items[${idx}].quantity must be a number`)
    if (typeof li.price !== 'string') throw new Error(`line_items[${idx}].price must be a string`)
  }
}

function formatOrderSummary(payload: ShopifyOrderPayload): string {
  const itemsSummary = payload.line_items
    .slice(0, 3)
    .map((li) => `${li.title} x${li.quantity}`)
    .join(', ')
  const more = payload.line_items.length > 3 ? ` +${payload.line_items.length - 3} more` : ''
  return `New order ${payload.name} from ${payload.email}: ${itemsSummary}${more} - Total: $${payload.total_price}`
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const order = payload as ShopifyOrderPayload

  const text = formatOrderSummary(order)

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel: config.slackChannel, text })
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = (await response.json()) as { ok: boolean; ts: string; channel: string }
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false for POST ${url}`)
  }

  return { slackMessageTs: data.ts, slackChannel: data.channel }
}

