  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      shopifyClientSecret: 'test-secret',
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.slackChannel).toBe('C1234567890')
    expect(result.slackMessageTs).toBe('1234567890.123456')
